// ---------------------------------------------------------------------------
// Node: Derive Idempotency Key
//
// Priority order:
//   1. X-GitHub-Delivery header — reused by GitHub on retries of the same
//      logical event, making it the ideal idempotency key.
//   2. Composite fallback from stable payload fields.
// ---------------------------------------------------------------------------
const headers = $input.first().json.headers ?? {};
const payload = $input.first().json.body ?? {};

const deliveryId = headers['x-github-delivery'] ?? headers['X-GitHub-Delivery'];
const action      = payload.action ?? 'unknown';
const repo        = payload.repository?.full_name ?? 'unknown';
const itemNumber  = payload.issue?.number ?? payload.pull_request?.number ?? 0;

const key = deliveryId
  ? deliveryId
  : `fallback:${repo}:${itemNumber}:${action}`;

console.log(`[idempotency] derived key=${key}`);

return [{ json: { ...payload, _idempotencyKey: key, _headers: headers } }];

// ---------------------------------------------------------------------------
// Node: Idempotency Gate (check-and-set against n8n Static Data)
//
// n8n Static Data persists across executions within the same workflow
// instance. For multi-instance deployments, replace this node with an
// HTTP Request to a shared Redis or key-value endpoint.
// ---------------------------------------------------------------------------
const staticData = $getWorkflowStaticData('global');
const processedKeys = staticData.processedKeys ?? {};

const key = $input.first().json._idempotencyKey;

if (processedKeys[key]) {
  const prior = processedKeys[key];
  console.log(
    `[idempotency] DUPLICATE suppressed key=${key} first_seen=${prior.processedAt}`
  );
  return [
    {
      json: {
        ...$input.first().json,
        _idempotencyDecision: 'duplicate',
        _priorProcessedAt: prior.processedAt,
      },
    },
  ];
}

// Persist BEFORE downstream mutation (check-and-set semantics).
processedKeys[key] = { processedAt: new Date().toISOString() };
staticData.processedKeys = processedKeys;

console.log(`[idempotency] FIRST processing key=${key}`);

return [
  {
    json: {
      ...$input.first().json,
      _idempotencyDecision: 'first',
    },
  },
];

// ---------------------------------------------------------------------------
// Node: Log Duplicate Suppression
// Emits a structured log entry so duplicate events are fully observable.
// ---------------------------------------------------------------------------
const key  = $input.first().json._idempotencyKey;
const when = $input.first().json._priorProcessedAt;
console.log(
  `[idempotency] DUPLICATE_SUPPRESSED key=${key} original_processing=${when}`
);
return [{ json: { suppressed: true, key, priorProcessedAt: when } }];

// ---------------------------------------------------------------------------
// Node: Build ClickUp Comment
// Constructs the comment body from the GitHub issue/PR event payload.
// Adjust `listId` / `taskId` mapping to match your ClickUp space.
// ---------------------------------------------------------------------------
const payload = $input.first().json;
const issue   = payload.issue ?? payload.pull_request ?? {};
const repo    = payload.repository?.full_name ?? 'unknown';
const action  = payload.action ?? 'unknown';
const actor   = payload.sender?.login ?? 'unknown';
const key     = payload._idempotencyKey;

const commentText =
  `**GitHub event** \`${action}\` on \`${repo}\` #${issue.number ?? '?'}` +
  `\nActor: ${actor}` +
  `\nURL: ${issue.html_url ?? ''}` +
  `\n\n_idempotency-key: ${key}_`;

return [{ json: { commentText, idempotencyKey: key, issueNumber: issue.number } }];

// ---------------------------------------------------------------------------
// Node: Log First Processing
// Emits a structured log entry for the successful, non-duplicate path.
// ---------------------------------------------------------------------------
const key    = $input.first().json.idempotencyKey;
const taskId = $vars.CLICKUP_TASK_ID;
console.log(
  `[idempotency] FIRST_PROCESSED key=${key} clickup_task=${taskId} ts=${new Date().toISOString()}`
);
return [{ json: { processed: true, key } }];
